/*
 * A287307  Primes that can be generated by the concatenation in base 6, in
 *          descending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287307
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 28, u32 n <= 28, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   concat_base6, digits_base6, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes A287307 by brute‑force search:
   for successive pairs (b,b+1) compute the value (b+1)*6^d + b,
   where d is the number of base‑6 digits of b, test if that value is
   prime, and keep the primes in order. */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"
#include "../utils/concat_base6.h"
#include "../utils/digits_base6.h"

/* sequence function */
seq_t a(idx_t n) {
    static seq_t *cache = NULL;
    static size_t cap   = 0;
    static idx_t count  = 0;
    static idx_t next_b = 1;   /* start with pair (1,2) */

    while (count < n) {
        seq_t val = concat_base6(next_b);
        if (is_prime_big(val)) {
            if (count == cap) {
                size_t newcap = cap ? cap * 2 : 4;
                seq_t *newarr = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
                if (!newarr) abort(); /* unlikely in tests */
                cache = newarr;
                cap   = newcap;
            }
            cache[count++] = val;
        }
        next_b++; /* move to next pair */
    }
    return cache[n - 1];
}
